"""Service-side UUIDv7: every contract `Id` is an UUIDv7 generated by the server.

The contract's `Id` pattern is strict (`...-7xxx-[89ab]xxx-...`), so the generator lives here
instead of being improvised per module. Layout (RFC 9562 §5.7): 48-bit Unix
timestamp in milliseconds, version nibble 7, 12 random bits, variant 10, 62 random bits.
"""

from __future__ import annotations

import secrets
import time
import uuid

__all__ = ["uuid7", "trace_id"]


def uuid7() -> str:
    """A lowercase UUIDv7 string, monotonic per millisecond only by timestamp (random tail)."""
    milliseconds = int(time.time() * 1000) & ((1 << 48) - 1)
    random_bits = secrets.randbits(74)
    value = milliseconds << 80
    value |= 0x7 << 76
    value |= ((random_bits >> 62) & 0xFFF) << 64
    value |= 0b10 << 62
    value |= random_bits & ((1 << 62) - 1)
    return str(uuid.UUID(int=value))


def trace_id() -> str:
    """A W3C trace-id (32 lowercase hex), non-zero as the specification requires."""
    return uuid.uuid4().hex
